Theory and Visualization

%%  Visualizing Gamma (2D) and Beta (3D Surface)
clear; clc; close all;

% 1. Plotting Continuous Gamma Function
x_gamma = linspace(0.1, 5, 200);
y_gamma = gamma(x_gamma);

subplot(1, 2, 1);
plot(x_gamma, y_gamma, 'b-', 'LineWidth', 2);
hold on;
% Plot integer factorial anchor points: (n, (n-1)!)
intervals = 1:5;
plot(intervals, gamma(intervals), 'ro', 'MarkerFaceColor', 'r', 'MarkerSize', 6);
xlabel('x'); ylabel('\Gamma(x)');

% 2. Plotting Beta Function 3D Surface
[M, N] = meshgrid(0.5:0.1:4, 0.5:0.1:4);
B_surface = beta(M, N);

subplot(1, 2, 2);
surf(M, N, B_surface);
xlabel('Parameter m'); ylabel('Parameter n'); zlabel('B(m,n)');

